import * as React from 'react'
import { ChevronLeft, ChevronRight, Command as CommandIcon, Loader2 } from 'lucide-react'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from '@/components/ui/dialog'
import {
  Command,
  CommandInput,
  CommandList,
  CommandEmpty,
  CommandGroup,
  CommandItem,
  CommandShortcut,
} from '@/components/ui/command'
import { Button } from '@/components/ui/button'
import { useControllableState, useDebouncedValue } from '@/components/ui/util'

export interface PaletteAction {
  id: string
  label: string
  description?: string
  group?: string
  keywords?: string[]
  shortcut?: string
  icon?: React.ReactNode
  disabled?: boolean
  children?: PaletteAction[]
  onSelect?: (context: {
    signal: AbortSignal
    close: () => void
    action: PaletteAction
  }) => void | Promise<void>
  keepOpen?: boolean
}
export interface CommandPaletteProps {
  actions: PaletteAction[]
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  title?: string
  description?: string
  placeholder?: string
  shortcut?: string | false
  enableInInputs?: boolean
  loadActions?: (
    query: string,
    context: { signal: AbortSignal; path: string[] },
  ) => Promise<PaletteAction[]>
  onAction?: (action: PaletteAction) => void
  children?: React.ReactNode
}
interface PaletteContext {
  id: string
  open: boolean
  setOpen: (value: boolean) => void
  title: string
  description: string
  placeholder: string
  shortcut: string | false
  query: string
  setQuery: (value: string) => void
  path: PaletteAction[]
  back: () => void
  actions: PaletteAction[]
  loading: boolean
  error: string
  pending: boolean
  serverSearch: boolean
  retry: () => void
  run: (action: PaletteAction) => void
}
const Context = React.createContext<PaletteContext | null>(null)
/** Reads palette state for custom triggers, contents, and action renderers. */
export function useCommandPalette() {
  const context = React.useContext(Context)
  if (!context) throw new Error('Command palette parts must be inside CommandPalette.')
  return context
}
/** Provides grouped and nested commands, async search cancellation, and a configurable global shortcut. */
export function CommandPalette({
  actions,
  open,
  defaultOpen = false,
  onOpenChange,
  title = 'Command palette',
  description = 'Search for a destination or action.',
  placeholder = 'What would you like to do?',
  shortcut = 'mod+k',
  enableInInputs = false,
  loadActions,
  onAction,
  children,
}: CommandPaletteProps) {
  const [shown, setShown] = useControllableState({
    value: open,
    defaultValue: defaultOpen,
    onChange: onOpenChange,
  })
  const [query, setQuery] = React.useState(''),
    [path, setPath] = React.useState<PaletteAction[]>([]),
    [remote, setRemote] = React.useState<PaletteAction[]>([]),
    [loading, setLoading] = React.useState(false),
    [error, setError] = React.useState(''),
    [pending, setPending] = React.useState(false),
    [revision, retry] = React.useReducer((n) => n + 1, 0)
  const debounced = useDebouncedValue(query),
    id = React.useId(),
    pathKey = JSON.stringify(path.map((item) => item.id)),
    operation = React.useRef<AbortController | null>(null)
  React.useEffect(() => {
    if (!shown) {
      setQuery('')
      setPath([])
      setError('')
      setPending(false)
      operation.current?.abort()
    }
  }, [shown])
  React.useEffect(() => () => operation.current?.abort(), [])
  React.useEffect(() => {
    if (!shortcut) return
    const keys = shortcut.toLowerCase().split('+'),
      key = keys.at(-1)
    const handle = (event: KeyboardEvent) => {
      if (event.defaultPrevented || event.repeat || event.key.toLowerCase() !== key) return
      const target = event.target as HTMLElement | null
      const ownInput =
        target?.closest('[data-command-palette]')?.getAttribute('data-command-palette') === id
      if (
        !enableInInputs &&
        !ownInput &&
        target?.closest('input,textarea,[contenteditable="true"]')
      )
        return
      if (
        keys.includes('mod')
          ? !(event.ctrlKey || event.metaKey)
          : keys.includes('ctrl') !== event.ctrlKey || keys.includes('meta') !== event.metaKey
      )
        return
      if (keys.includes('shift') !== event.shiftKey || keys.includes('alt') !== event.altKey) return
      event.preventDefault()
      setShown(!shown)
    }
    document.addEventListener('keydown', handle, true)
    return () => document.removeEventListener('keydown', handle, true)
  }, [shortcut, enableInInputs, shown, setShown, id])
  React.useEffect(() => {
    if (!shown || !loadActions) {
      setLoading(false)
      return
    }
    setLoading(true)
    setError('')
    setRemote([])
    if (query !== debounced) return
    const controller = new AbortController()
    Promise.resolve()
      .then(() =>
        loadActions(debounced, {
          signal: controller.signal,
          path: JSON.parse(pathKey) as string[],
        }),
      )
      .then((result) => {
        if (!controller.signal.aborted) setRemote(result)
      })
      .catch((reason) => {
        if (!controller.signal.aborted) setError(String(reason))
      })
      .finally(() => {
        if (!controller.signal.aborted) setLoading(false)
      })
    return () => controller.abort()
  }, [shown, loadActions, query, debounced, pathKey, revision])
  const current = loadActions ? remote : (path.at(-1)?.children ?? actions)
  const duplicate = new Set(current.map((item) => item.id)).size !== current.length
  const run = async (action: PaletteAction) => {
    if (action.disabled || pending) return
    if (action.children) {
      setPath((previous) => [...previous, action])
      setQuery('')
      return
    }
    operation.current?.abort()
    const controller = new AbortController()
    operation.current = controller
    setPending(true)
    setError('')
    try {
      await action.onSelect?.({ signal: controller.signal, close: () => setShown(false), action })
      if (!controller.signal.aborted) {
        onAction?.(action)
        if (!action.keepOpen) setShown(false)
      }
    } catch (reason) {
      if (!controller.signal.aborted) setError(String(reason))
    } finally {
      if (!controller.signal.aborted) setPending(false)
    }
  }
  return (
    <Context.Provider
      value={{
        open: shown,
        id,
        setOpen: setShown,
        title,
        description,
        placeholder,
        shortcut,
        query,
        setQuery,
        path,
        back: () => {
          setPath((previous) => previous.slice(0, -1))
          setQuery('')
          setError('')
        },
        actions: duplicate ? [] : current,
        loading,
        error: duplicate ? 'Action IDs must be unique.' : error,
        pending,
        serverSearch: !!loadActions,
        retry,
        run,
      }}
    >
      {children ?? (
        <>
          <CommandPaletteTrigger />
          <CommandPaletteContent remote={!!loadActions} />
        </>
      )}
    </Context.Provider>
  )
}
/** Opens the palette using an ordinary button that can be replaced or styled by the caller. */
export function CommandPaletteTrigger({
  children,
  onClick,
  ...props
}: React.ComponentProps<typeof Button>) {
  const c = useCommandPalette()
  return (
    <Button
      type="button"
      variant="outline"
      {...props}
      onClick={(event) => {
        onClick?.(event)
        if (!event.defaultPrevented) c.setOpen(true)
      }}
    >
      {children ?? (
        <>
          <CommandIcon />
          Search commands
          {c.shortcut && (
            <kbd className="ms-6 rounded border px-1.5 text-[10px] text-muted-foreground">
              {c.shortcut.replace('mod', 'Ctrl / ⌘')}
            </kbd>
          )}
        </>
      )}
    </Button>
  )
}
/** Renders the accessible command dialog and restores the element focused before opening. */
export function CommandPaletteContent({
  remote,
  className,
}: {
  remote?: boolean
  className?: string
}) {
  const c = useCommandPalette(),
    previousFocus = React.useRef<HTMLElement | null>(null)
  const groups = [...new Set(c.actions.map((item) => item.group ?? 'Actions'))]
  return (
    <Dialog open={c.open} onOpenChange={c.setOpen}>
      <DialogContent
        data-command-palette={c.id}
        className={className}
        onOpenAutoFocus={() => {
          previousFocus.current =
            document.activeElement instanceof HTMLElement ? document.activeElement : null
        }}
        onCloseAutoFocus={(event) => {
          if (previousFocus.current?.isConnected) {
            event.preventDefault()
            previousFocus.current.focus()
          }
        }}
        onEscapeKeyDown={(event) => {
          if (c.path.length) {
            event.preventDefault()
            c.back()
          }
        }}
      >
        <DialogHeader>
          <DialogTitle>{c.title}</DialogTitle>
          <DialogDescription>{c.description}</DialogDescription>
        </DialogHeader>
        {c.path.length > 0 && (
          <Button type="button" size="sm" variant="ghost" className="w-fit" onClick={c.back}>
            <ChevronLeft />
            Back · {c.path.at(-1)?.label}
          </Button>
        )}
        <Command label="Search commands" shouldFilter={!(remote ?? c.serverSearch)}>
          <CommandInput
            aria-label="Search commands"
            placeholder={c.placeholder}
            value={c.query}
            onValueChange={c.setQuery}
            onKeyDown={(event) => {
              if (event.key === 'Backspace' && !c.query && c.path.length) {
                event.preventDefault()
                c.back()
              }
            }}
          />
          <CommandList aria-label="Available commands" aria-busy={c.loading || c.pending}>
            {c.loading ? (
              <p
                role="status"
                className="flex items-center gap-2 p-4 text-sm text-muted-foreground"
              >
                <Loader2 className="size-4 animate-spin" />
                Searching commands…
              </p>
            ) : (
              <>
                <CommandEmpty>No commands found.</CommandEmpty>
                {groups.map((group) => (
                  <CommandGroup key={group} heading={group}>
                    {c.actions
                      .filter((item) => (item.group ?? 'Actions') === group)
                      .map((action) => (
                        <CommandPaletteItem key={action.id} action={action} />
                      ))}
                  </CommandGroup>
                ))}
              </>
            )}
          </CommandList>
        </Command>
        {c.error && (
          <div
            role="alert"
            className="rounded-lg border border-destructive/30 p-3 text-sm text-destructive"
          >
            {c.error}
            {(remote ?? c.serverSearch) && (
              <Button type="button" size="sm" variant="ghost" onClick={c.retry}>
                Retry
              </Button>
            )}
          </div>
        )}
        <p role="status" className="text-xs text-muted-foreground">
          {c.pending
            ? 'Running command…'
            : '↑ ↓ to navigate · Enter to select · Escape to go back or close'}
        </p>
      </DialogContent>
    </Dialog>
  )
}
/** Renders one command while preserving its search keywords, disabled state, and nested navigation. */
export function CommandPaletteItem({ action }: { action: PaletteAction }) {
  const c = useCommandPalette()
  return (
    <CommandItem
      value={action.id}
      keywords={[action.label, action.description ?? '', ...(action.keywords ?? [])]}
      disabled={action.disabled || c.pending}
      onSelect={() => void c.run(action)}
    >
      {action.icon && <span aria-hidden="true">{action.icon}</span>}
      <span className="min-w-0 flex-1">
        <span className="block truncate">{action.label}</span>
        {action.description && (
          <span className="block truncate text-xs text-muted-foreground">{action.description}</span>
        )}
      </span>
      {action.shortcut && <CommandShortcut>{action.shortcut}</CommandShortcut>}
      {action.children && <ChevronRight aria-hidden="true" className="ms-auto size-4" />}
    </CommandItem>
  )
}

import { usePortalContainer } from '@/components/ui/config-provider'
import * as React from 'react'
import { cn } from '@/lib/utils'
import { XIcon } from 'lucide-react'
import { Dialog as DialogPrimitive } from 'radix-ui'

import { Button } from '@/components/ui/button'

function Dialog({ ...props }: React.ComponentProps<typeof DialogPrimitive.Root>) {
  return <DialogPrimitive.Root data-slot="dialog" {...props} />
}

function DialogTrigger({ ...props }: React.ComponentProps<typeof DialogPrimitive.Trigger>) {
  return <DialogPrimitive.Trigger data-slot="dialog-trigger" {...props} />
}

function DialogPortal({ ...props }: React.ComponentProps<typeof DialogPrimitive.Portal>) {
  return (
    <DialogPrimitive.Portal container={usePortalContainer()} data-slot="dialog-portal" {...props} />
  )
}

function DialogClose({ ...props }: React.ComponentProps<typeof DialogPrimitive.Close>) {
  return <DialogPrimitive.Close data-slot="dialog-close" {...props} />
}

function DialogOverlay({
  className,
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Overlay>) {
  return (
    <DialogPrimitive.Overlay
      data-slot="dialog-overlay"
      className={cn(
        'fixed inset-0 z-50 bg-black/50 data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:animate-in data-[state=open]:fade-in-0',
        className,
      )}
      {...props}
    />
  )
}

function DialogContent({
  className,
  children,
  showCloseButton = true,
  draggable,
  resizable,
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Content> & {
  showCloseButton?: boolean
  draggable?: boolean
  resizable?: boolean
}) {
  const [position, setPosition] = React.useState({ x: 0, y: 0 }),
    drag = React.useRef<{
      x: number
      y: number
      px: number
      py: number
      limitX: number
      limitY: number
    } | null>(null)
  return (
    <DialogPortal data-slot="dialog-portal">
      <DialogOverlay />
      <DialogPrimitive.Content
        data-slot="dialog-content"
        className={cn(
          'fixed top-[50%] left-[50%] z-50 grid w-full max-w-[calc(100%-2rem)] translate-x-[-50%] translate-y-[-50%] gap-4 rounded-lg border bg-background p-6 shadow-lg duration-200 outline-none data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=closed]:zoom-out-95 data-[state=open]:animate-in data-[state=open]:fade-in-0 data-[state=open]:zoom-in-95 sm:max-w-lg',
          className,
        )}
        {...props}
        style={{
          ...(draggable
            ? {
                transform: `translate(calc(-50% + ${position.x}px),calc(-50% + ${position.y}px))`,
                translate: 'none',
              }
            : {}),
          ...(resizable
            ? {
                resize: 'both',
                width: 'min(512px,calc(100vw - 32px))',
                overflow: 'auto',
                minWidth: 260,
                minHeight: 150,
                maxWidth: 'calc(100vw - 32px)',
                maxHeight: 'calc(100vh - 32px)',
              }
            : {}),
          ...props.style,
        }}
        onPointerDown={(event) => {
          props.onPointerDown?.(event)
          if (
            !draggable ||
            (event.target as HTMLElement).closest('button,input,textarea,select,a') ||
            !(event.target as HTMLElement).closest(
              '[data-slot="dialog-header"],[data-slot="dialog-title"]',
            )
          )
            return
          const bounds = event.currentTarget.getBoundingClientRect()
          drag.current = {
            x: event.clientX,
            y: event.clientY,
            px: position.x,
            py: position.y,
            limitX: Math.max(0, (innerWidth - bounds.width) / 2 - 16),
            limitY: Math.max(0, (innerHeight - bounds.height) / 2 - 16),
          }
          event.currentTarget.setPointerCapture(event.pointerId)
        }}
        onPointerMove={(event) => {
          props.onPointerMove?.(event)
          if (drag.current)
            setPosition({
              x: Math.max(
                -drag.current.limitX,
                Math.min(drag.current.limitX, drag.current.px + event.clientX - drag.current.x),
              ),
              y: Math.max(
                -drag.current.limitY,
                Math.min(drag.current.limitY, drag.current.py + event.clientY - drag.current.y),
              ),
            })
        }}
        onPointerUp={(event) => {
          drag.current = null
          props.onPointerUp?.(event)
        }}
        onLostPointerCapture={() => {
          drag.current = null
        }}
      >
        {children}
        {showCloseButton && (
          <DialogPrimitive.Close
            data-slot="dialog-close"
            className="absolute top-4 right-4 rounded-xs opacity-70 ring-offset-background transition-opacity hover:opacity-100 focus:ring-2 focus:ring-ring focus:ring-offset-2 focus:outline-hidden disabled:pointer-events-none data-[state=open]:bg-accent data-[state=open]:text-muted-foreground [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4"
          >
            <XIcon />
            <span className="sr-only">Close</span>
          </DialogPrimitive.Close>
        )}
      </DialogPrimitive.Content>
    </DialogPortal>
  )
}

function DialogHeader({ className, ...props }: React.ComponentProps<'div'>) {
  return (
    <div
      data-slot="dialog-header"
      className={cn('flex flex-col gap-2 text-center sm:text-left', className)}
      {...props}
    />
  )
}

function DialogFooter({
  className,
  showCloseButton = false,
  children,
  ...props
}: React.ComponentProps<'div'> & {
  showCloseButton?: boolean
}) {
  return (
    <div
      data-slot="dialog-footer"
      className={cn('flex flex-col-reverse gap-2 sm:flex-row sm:justify-end', className)}
      {...props}
    >
      {children}
      {showCloseButton && (
        <DialogPrimitive.Close asChild>
          <Button variant="outline">Close</Button>
        </DialogPrimitive.Close>
      )}
    </div>
  )
}

function DialogTitle({ className, ...props }: React.ComponentProps<typeof DialogPrimitive.Title>) {
  return (
    <DialogPrimitive.Title
      data-slot="dialog-title"
      className={cn('text-lg leading-none font-semibold', className)}
      {...props}
    />
  )
}

function DialogDescription({
  className,
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Description>) {
  return (
    <DialogPrimitive.Description
      data-slot="dialog-description"
      className={cn('text-sm text-muted-foreground', className)}
      {...props}
    />
  )
}

export {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogOverlay,
  DialogPortal,
  DialogTitle,
  DialogTrigger,
}

import { contrastForeground } from '@/lib/contrast'
import * as React from 'react'
import { cn } from '@/lib/utils'
import { Direction } from 'radix-ui'
export interface UIConfig {
  density: 'comfortable' | 'compact'
  direction: 'ltr' | 'rtl'
  locale: string
}
const ConfigContext = React.createContext<UIConfig>({
  density: 'comfortable',
  direction: 'ltr',
  locale: 'en-US',
})
const PortalContext = React.createContext<HTMLElement | null>(null)
export const usePortalContainer = () => React.useContext(PortalContext) ?? undefined
export const useUIConfig = () => React.useContext(ConfigContext)
export interface ConfigProviderProps extends React.HTMLAttributes<HTMLDivElement> {
  density?: UIConfig['density']
  direction?: UIConfig['direction']
  locale?: string
  accent?: string
  radius?: number
}
export function ConfigProvider({
  density: providedDensity,
  direction: providedDirection,
  locale: providedLocale,
  accent,
  radius,
  children,
  style,
  className,
  ...props
}: ConfigProviderProps) {
  const parent = useUIConfig(),
    density = providedDensity ?? parent.density,
    direction = providedDirection ?? parent.direction,
    locale = providedLocale ?? parent.locale
  const [portal, setPortal] = React.useState<HTMLDivElement | null>(null)
  return (
    <ConfigContext.Provider value={{ density, direction, locale }}>
      <PortalContext.Provider value={portal}>
        <Direction.Provider dir={direction}>
          <div
            dir={direction}
            lang={locale}
            data-density={density}
            className={cn('ergon-root', className)}
            style={
              {
                '--ergon-control-height': density === 'compact' ? '30px' : '2.25rem',
                '--ergon-control-py': density === 'compact' ? '0.25rem' : '0.5rem',
                ...(accent
                  ? {
                      '--primary': accent,
                      '--ring': accent,
                      '--primary-foreground': contrastForeground(accent),
                    }
                  : {}),
                ...(radius !== undefined ? { '--radius': `${radius}px` } : {}),
                ...style,
              } as React.CSSProperties
            }
            {...props}
          >
            {children}
            <div ref={setPortal} data-ergon-portals="" style={{ display: 'contents' }} />
          </div>
        </Direction.Provider>
      </PortalContext.Provider>
    </ConfigContext.Provider>
  )
}

import { clsx, type ClassValue } from 'clsx'
import { twMerge } from 'tailwind-merge'
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

import * as React from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from '@/lib/utils'
import { Slot } from 'radix-ui'
import { Loader2 } from 'lucide-react'

const buttonVariants = cva(
  "inline-flex shrink-0 items-center justify-center gap-2 rounded-md text-sm font-medium whitespace-nowrap transition-all outline-none focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        default: 'bg-primary text-primary-foreground hover:bg-primary/90',
        destructive:
          'bg-destructive text-white hover:bg-destructive/90 focus-visible:ring-destructive/20 dark:bg-destructive/60 dark:focus-visible:ring-destructive/40',
        outline:
          'border bg-background shadow-xs hover:bg-accent hover:text-accent-foreground dark:border-input dark:bg-input/30 dark:hover:bg-input/50',
        secondary: 'bg-secondary text-secondary-foreground hover:bg-secondary/80',
        ghost: 'hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent/50',
        link: 'text-primary underline-offset-4 hover:underline',
        soft: 'bg-primary/10 text-primary hover:bg-primary/15',
        success: 'bg-emerald-600 text-white hover:bg-emerald-700',
        warning: 'bg-amber-400 text-amber-950 hover:bg-amber-500',
        dashed:
          'border border-dashed bg-background text-foreground hover:border-primary hover:text-primary',
      },
      size: {
        default:
          'h-[var(--ergon-control-height,2.25rem)] px-4 py-[var(--ergon-control-py,0.5rem)] has-[>svg]:px-3',
        xs: "h-6 gap-1 rounded-md px-2 text-xs has-[>svg]:px-1.5 [&_svg:not([class*='size-'])]:size-3",
        sm: 'h-8 gap-1.5 rounded-md px-3 has-[>svg]:px-2.5',
        lg: 'h-10 rounded-md px-6 has-[>svg]:px-4',
        icon: 'size-9',
        'icon-xs': "size-6 rounded-md [&_svg:not([class*='size-'])]:size-3",
        'icon-sm': 'size-8',
        'icon-lg': 'size-10',
      },
    },
    defaultVariants: {
      variant: 'default',
      size: 'default',
    },
  },
)

/**
 * Composes button variants, loading state, and optional slot rendering. Compact-density styles travel with the installed source.
 */
function Button({
  className,
  variant = 'default',
  size = 'default',
  asChild = false,
  loading = false,
  children,
  ...props
}: React.ComponentProps<'button'> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean
    loading?: boolean
  }) {
  const Comp = asChild ? Slot.Root : 'button'

  return (
    <Comp
      data-slot="button"
      data-variant={variant}
      data-size={size}
      className={cn(buttonVariants({ variant, size }), className)}
      aria-busy={loading || undefined}
      {...props}
      disabled={props.disabled || loading}
    >
      {asChild ? (
        children
      ) : (
        <>
          {loading && <Loader2 className="animate-spin" />}
          {children}
        </>
      )}
    </Comp>
  )
}

export { Button, buttonVariants }

'use client'

